package com.kuaima.app.admin.entity;
import java.time.LocalDateTime;import jakarta.persistence.*;import lombok.Getter;import lombok.Setter;
@Entity @Table(name="reward_campaign",indexes={@Index(name="idx_reward_status_send",columnList="status,send_at"),@Index(name="idx_reward_created",columnList="created_at"),@Index(name="idx_reward_target",columnList="target")}) @Getter @Setter
public class RewardCampaign {@Id @GeneratedValue(strategy=GenerationType.IDENTITY)private Long id;@Column(nullable=false,unique=true,length=40)private String rewardNo;@Column(nullable=false,length=100)private String name;@Column(nullable=false,length=20)private String target;@Column(nullable=false,length=20)private String scope;@Column(columnDefinition="TEXT")private String users;private Integer plannedCount;@Column(nullable=false,length=20)private String amountMode;private Long amount;private Long minAmount;private Long maxAmount;private Long totalAmount;@Column(nullable=false,length=20)private String status;private String sendMode;private LocalDateTime sendAt;private LocalDateTime createdAt;@Column(length=500)private String remark;private Long operatorId;private String operatorName;private Integer actualCount=0;private Long actualAmount=0L;private Integer failedCount=0;@Column(length=1000)private String errorMessage;}
